def _inventory(fen):
    board = chess.Board(fen)
    sides = []
    for color, name in ((chess.WHITE, 'White'), (chess.BLACK, 'Black')):
        groups = []
        for piece_type in (chess.KING, chess.QUEEN, chess.ROOK, chess.BISHOP, chess.KNIGHT, chess.PAWN):
            squares = board.pieces(piece_type, color)
            if squares:
                groups.append(chess.piece_name(piece_type) + ('s' if len(squares) > 1 else '') +
                              ' ' + ', '.join(chess.square_name(s) for s in squares))
        sides.append(name + ': ' + '; '.join(groups))
    return 'White to move. ' + '. '.join(sides) + '.'


def _add(number, title, summary, board_text, key_text, defence_text, method_text,
         key_note, branches, concepts, recap):
    source = _SOURCE[number]
    identifier = f'app-two-{number:02d}'
    inventory = _inventory(source['fen'])
    answers = source['answers']
    DEFENCE_ANSWERS[identifier] = dict(answers)
    groups = {}
    for defence, finish in answers.items():
        groups.setdefault(finish, []).append(defence)
    reply_map = ' '.join('After ' + ', '.join(defences) + ': ' + finish + '.'
                         for finish, defences in groups.items())
    examples = tuple(example(
        f'{source["key"]} {defence} {finish}', source['fen'],
        (source['key'], defence, finish),
        (inventory, key_note, defence_note, finish_note))
        for defence, finish, defence_note, finish_note in branches)
    choices = [(source['key'], True, 'This key gives a mate on White’s next turn against every legal defence.')]
    for wrong, refutation in source['wrong']:
        explanation = ('This leaves Black stalemated: no check and no legal move.' if refutation == 'stalemate'
                       else f'Black can answer {refutation}, after which White has no immediate mate. The two-move task fails.')
        choices.append((wrong, False, explanation))
    checks = tuple(check(f'{identifier}-concept-{i}', prompt,
                         (correct, True, why), (wrong, False, correction))
                   for i, (prompt, correct, why, wrong, correction) in enumerate(concepts, 1))
    GUIDES[identifier] = guide(
        (source['page'], 396),
        ('Explain the key before replaying the answer.', 'Find a mating reply to every legal Black move.'),
        (
            section('Read the position and the task',
                    f'Two-mover {number}, {source["author"]}. ' + inventory + ' ' + board_text),
            section('Understand the first move', key_text),
            section('Give the defender a real choice', defence_text),
            section('Practise and check your reasoning', method_text),
            section('Complete defence map',
                    f'The key {source["key"]} leaves {len(answers)} legal Black replies. '
                    'Each reply below has a verified mate on the next move. A comma-separated group means '
                    'the same finish works after any one of those alternatives; it is not a move sequence. '
                    'Some positions permit another mating finish too. ' + reply_map),
        ), examples,
        tuple(f'{san}: {explanation}' for san, _, explanation in choices[1:]),
        checks, recap)
    EXERCISES.append(dict(
        id=identifier, title=f'Two-mover {number} · {title}', summary=summary,
        fen=source['fen'], inventory=inventory,
        prompt='White to move: find the first move that guarantees mate on White’s second move.',
        choices=tuple(choices), objective='mate_in_2'))


_add(1, 'Offer the queen to activate several mates',
     'Shumov’s queen offer coordinates three different mating pieces. Black can choose what to capture, but cannot stop every finish.',
     '''The black king on d6 is surrounded by a crowded mixture of friendly and hostile units. Do not let the large number of pieces make you rush into a check. Locate White's potential checking squares: b5 for the c3 knight, e6 for the rook, and e7 for the bishop. The task is to make those possibilities cooperate so that Black cannot neutralize all of them with one reply.''',
     '''The key is Qf7. White offers the queen to both the bishop g8 and the rook h7. That looks expensive in an ordinary material count, but the problem ends on White's next move. The queen also takes control of important squares near d6 while remaining ready to support the other attackers. The point is a network of threats: when Black spends a move stopping one mating route, another survives. An offered queen is justified by that complete calculation, not by the fact that sacrifices sometimes look impressive.''',
     '''If the bishop accepts with Bxf7, Be7 is mate; the bishop reaches the diagonal beside the king. If the rook accepts with Rxf7, Re6 is mate instead. A knight capture on b6 does not rescue Black: Nb5 still delivers the required check. The defence Ne5 is especially useful to study because it puts a black knight directly on a pawn's capture square; dxe5 then mates. Several other replies allow two or more finishes, so do not confuse a unique first move with a unique answer in every branch.''',
     '''Replay the two queen captures separately and identify which black piece changed its defensive job. Then reset and cover the answers. For each of Black's possible moves, ask which of Be7, Nb5, or Re6 still works; inspect the special Ne5 pawn capture as well. At the final position, verify check, king flights, captures, and possible blocks. Your practical lesson is to compare several concrete threats after a sacrifice instead of assuming that the opponent must accept it in the most convenient way.''',
     'Qf7 offers the queen while arranging several mating routes around d6.',
     [('Bxf7','Be7#','The g8 bishop captures the offered queen.','The bishop moves g5–f6–e7 and checks d6; Black has no legal answer.'),
      ('Rxf7','Re6#','The h7 rook accepts the queen instead.','Re6 checks along the sixth rank and completes the mating net.'),
      ('Nxb6','Nb5#','The d7 knight captures the pawn b6.','Nc3–b5 checks d6. Taking a pawn did not eliminate this mating route.'),
      ('Ne5','dxe5#','The d7 knight blocks on e5.','The d4 pawn captures e5 and attacks the king on d6.')],
     [('Why can White offer the queen on f7?', 'A mating reply survives every legal defence', 'The task ends before Black can use the extra material.', 'Black is obliged to capture the queen', 'Black may choose any legal move; every choice must be answered.'),
      ('After Rxf7, which white unit gives the demonstrated mate?', 'The rook from e4 to e6', 'The rook checks d6 along the sixth rank.', 'The queen on f7', 'Black has just captured that queen; it cannot make the next move.')],
     ('Name several mating routes.', 'Calculate both queen captures.', 'The key is unique; some finishes are not.'))

_add(2, 'A rook offer makes room for the queen',
     'Galitsky’s Rd2 invites a bishop capture and prepares different finishes according to whether Black moves the bishop or king.',
     '''Only six pieces are present, so begin with the black king's neighboring squares. The white knight f5 and king h5 already restrict it. The white queen a1 could use the first rank, but Black's bishop c1 sits on that rank. The rook a2 is active but cannot simply check from f2 safely. Look for a way to change the bishop's placement while preserving a reply to the king's remaining flight.''',
     '''Rd2 is a quiet rook sacrifice. From d2 the rook can check on f2 if Black moves the king to f4. At the same time it offers the bishop c1 a capture on d2. Accepting that offer removes the bishop from the first rank, letting the queen travel from a1 to f1. White does not need the rook to survive every variation: its role changes with Black's decision. This is a useful first example of one key preparing two different mating pieces.''',
     '''Black has exactly four legal replies after the key. The king may play Kf4, when Rf2 is mate: the rook now checks along the f-file and the supporting pieces deny escape. The bishop may move to a3 or b2, or capture the rook with Bxd2. Each of those three bishop moves clears c1, and Qf1 is mate. Grouping the bishop moves is more informative than memorizing four unrelated lines, because all three change the same line on the board.''',
     '''First replay Bxd2 and trace the queen's entire route a1–b1–c1–d1–e1–f1. Then reset and choose Kf4 instead. Explain why the rook must still be available in that branch. As a practical check, try the immediate Rf2+ before preparing anything: Black can capture it with Kxf2. The difference is the king's location and the geometry of the final net. A move that fails now can become mate after one carefully prepared change.''',
     'Rd2 offers the rook to the bishop and prepares Rf2 against a king move.',
     [('Bxd2','Qf1#','The bishop takes the rook and vacates c1.','The cleared first rank lets the queen reach f1 with mate.'),
      ('Kf4','Rf2#','Black preserves the bishop and moves the king to f4.','The rook checks along the f-file; the king cannot capture a rook two squares away.')],
     [('What do Ba3, Bb2, and Bxd2 have in common?', 'They clear c1 for the queen’s first-rank route', 'That is why Qf1 answers all three.', 'They all capture the rook', 'Only Bxd2 is a capture.'),
      ('Why does an immediate Rf2+ fail?', 'Black can capture with Kxf2', 'The king is still on f3 before the key.', 'Rooks cannot move from a2 to f2', 'That move is legal; its tactical consequence is the problem.')],
     ('Group defences by what they change.', 'A sacrifice may clear a line.', 'Compare the king’s square before and after the key.'))

_add(3, 'A rook changes the mating geometry',
     'Havel’s Rg4 creates distinct queen and rook mates for the black king’s three flights and the bishop’s moves.',
     '''The black king c2 is close to White's king a1, but the kings are not adjacent and the position is legal. White's bishop b4 guards important diagonals while the queen h1 and rook g1 wait on the first rank. The black bishop d1 can obstruct or capture along a diagonal. Rather than counting material, list the black king's available destinations and ask how a single rook move might prepare a different reply to each.''',
     '''The key Rg4 puts the rook on the fourth rank. From there it can reach c4, and it helps the arrangement needed for a queen check on e4. It also offers itself along the black bishop's diagonal d1–e2–f3–g4. This offer is intentional. If that bishop moves, White's queen gains access along the first rank toward b1. The rook's new square therefore connects a possible sacrifice, a rook mate, and a queen mate rather than merely making an attack on one piece.''',
     '''After Kc1, Rc4 is mate. After Kd3, Qe4 is mate; after Kb3, Qxd1 is mate. Keep those three king destinations paired with their own finishes. The bishop's legal replies are Be2, Bf3, and Bxg4. They all vacate d1, so Qb1 mates after each. The king move Kb3 is different: Black leaves the bishop on d1, and White captures that bishop with the mating queen. A capture sign in the notation records a real difference in the position.''',
     '''Use the board to rehearse one king branch and one bishop branch before consulting the full reply map. Trace the checking line and identify why the black king cannot take the checker. Then try the tempting immediate Rg2+: Black can play Kd3, and no mate is available on White's next move. Checking first is not a shortcut through the problem. The quiet move succeeds because it prepares the geometry for all the possible replies, including the one that defeats the premature check.''',
     'Rg4 prepares fourth-rank mates and invites the bishop to leave d1.',
     [('Kc1','Rc4#','The king steps down to c1.','The rook reaches c4 and checks along the c-file.'),
      ('Kd3','Qe4#','The king moves toward the centre.','The queen reaches e4 and checks diagonally beside the king.'),
      ('Kb3','Qxd1#','The king moves to b3 while the bishop remains on d1.','The queen captures that bishop and checks along d1–c2–b3.'),
      ('Bxg4','Qb1#','The bishop accepts the rook and clears d1.','The queen travels along the first rank to b1 and mates diagonally.')],
     [('Why do all three bishop replies allow Qb1?', 'Each removes the bishop from d1', 'The queen’s route along the first rank becomes clear.', 'The bishop must return to c2', 'No such move is required or available in those branches.'),
      ('After Kb3, why is the finish written Qxd1?', 'The queen captures the bishop still on d1', 'The x records the capture before the diagonal check.', 'The queen captures the king', 'Kings are never captured; mate ends the game.')],
     ('Pair each king flight with its finish.', 'Inspect the first-rank obstruction.', 'A quiet rook move can prepare several geometries.'))

_add(4, 'Offer a queen that different defenders cannot all take',
     'Petrov’s Qd7 invites several captures, yet the surviving rook mate depends on which defensive line Black changes.',
     '''Black has a queen, rook, two bishops, and a knight, while the king h8 remains cramped in the corner. White's rook e7 wants to mate on e8 or h7. The knight f6 and pawn h6 help make those squares powerful. Before choosing a check, notice Black's rook a7 and bishop a4: both can influence the seventh-rank struggle in different ways. The many defenders make a direct material comparison misleading for a two-move task.''',
     '''Qd7 is the key. The queen moves into a square where the rook a7, knight b8, or bishop a4 may capture her. Those captures are not equivalent. Moving a defender changes the lines available against White's rook, so the right finish must be selected afterward. The queen's placement also interferes with Black's coordination while supporting the attacking arrangement. You need not force one particular acceptance of the sacrifice; you need a mating answer whichever defender moves or declines the offer.''',
     '''If Black plays Rxd7, White answers Re8 mate. If Black uses the knight, Nxd7 is answered by Rh7 mate; Bxd7 permits the same finish. Capturing a support piece also changes the choice: Bxf6 allows Re8, whereas Bxh6 allows Rh7. These paired variations are a good way to learn the position. Many quieter moves permit both rook mates, but the critical captures show why neither finishing move should be played automatically against every defence.''',
     '''Start with the three captures of the queen. For each, physically remove the queen, move the actual capturing piece, and test both Re8 and Rh7. Mark the one that survives. Then use the complete reply map to handle the quieter alternatives. Contrast the key with immediate Rh7+: Black can answer Rxh7, so an attractive check has not solved anything. The reusable habit is to track lines and defenders after a sacrifice, rather than treating all moves to the same destination as the same position.''',
     'Qd7 offers the queen to three different black pieces while preparing the rook mates.',
     [('Rxd7','Re8#','The a7 rook takes the queen on d7.','The white rook checks from e8 and the corner king has no legal answer.'),
      ('Nxd7','Rh7#','The b8 knight captures the queen.','The rook reaches h7, where the knight f6 helps protect the mating square.'),
      ('Bxd7','Rh7#','The a4 bishop captures along a4–b5–c6–d7.','Rh7 completes the corner mate after this different capture.'),
      ('Bxf6','Re8#','The g5 bishop removes White’s knight.','Use the surviving e8 mating route instead of assuming Rh7 still works.')],
     [('Must White always finish with the same rook move?', 'No; choose the finish after seeing the defence', 'The captures alter different defensive lines.', 'Yes; a unique key requires one identical finish', 'A unique first move can lead to different second moves.'),
      ('Why is immediate Rh7+ insufficient?', 'Black can capture the rook with Rxh7', 'The a7 rook still has its seventh-rank defensive route.', 'White is forbidden to begin with check', 'Checks are legal; this particular check fails tactically.')],
     ('Track which defender captured.', 'Compare Re8 and Rh7.', 'Do not confuse a legal check with a forced mate.'))
_add(5, 'Place the queen in the far corner',
     'Loyd’s Qa1 makes every knight move and the only pawn move create its own mating answer.',
     '''The black king a5 looks almost boxed in already. Its knight a2 has three possible destinations, and the pawn b3 can advance. White has a queen in the centre, two knights, a rook, and a bishop, but a central queen square is not automatically the most useful one. Look especially at the two connected diagonals a1–b2–c3 and c3–b4–a5, and distinguish the white pawns a3 and a4: they do different jobs.''',
     '''Qa1 sends the queen to a corner without giving check. From a1 she can reach c3 after a black knight move. If the knight itself comes to c3 with check, the queen can capture it there and mate. If the knight chooses b4 instead, the pawn on a3 can capture it and give a pawn check to a5. The queen move also prepares the position for the b-pawn advance. This is a waiting key: White arranges answers and lets Black choose which change to make.''',
     '''The complete choice is small enough to learn directly. Nc1 permits Qc3 mate; Nc3+ permits Qxc3 mate. The plus sign on Black's move matters: White must answer the check, and capturing the knight does so. Nb4 is met by axb4 mate, using the pawn from a3, not the pawn a4. The remaining reply b2 is answered by Rc5 mate. Every legal Black move participates in a different visible change, so there is no need to invent a move that Black might prefer.''',
     '''Practise by naming Black's four replies before moving any white piece. After each reply, say which piece will check and why it can reach its destination. Reset and compare immediate Rc5+: Black escapes with Kxa4, so the same rook destination is not yet a solution. The key teaches patience with a fully restricted opponent. A move far from the enemy king can be precise because it prepares access to the right squares rather than simply moving closer.''',
     'Qa1 prepares queen access to c3 and leaves a mate for each black move.',
     [('Nc3+','Qxc3#','The knight checks the white king b1 from c3.','The queen captures the checking knight and checks a5 along c3–b4–a5.'),
      ('Nb4','axb4#','The knight goes to b4 instead.','The a3 pawn captures b4 and gives check to a5; the a4 pawn stays put.'),
      ('b2','Rc5#','The pawn advances from b3 to b2.','The rook checks across the fifth rank, with no legal escape.')],
     [('Which pawn plays axb4 after Nb4?', 'The pawn on a3', 'White pawns capture one rank forward, from a3 to b4.', 'The pawn on a4', 'From a4 a white pawn captures b5, not b4.'),
      ('Does Nc3+ refute the key by checking first?', 'No; Qxc3 both answers check and mates', 'White removes the checking knight legally.', 'Yes; a defender’s check always defeats a mate-in-two', 'A check can be answered by a mating move.')],
     ('List all four Black moves.', 'Use the correct a-pawn.', 'A checking defence may still permit mate.'))

_add(6, 'Use the edge of the board as a route',
     'Maksimov’s Qh8 prepares a long queen journey and a different bishop mate if the king runs to b7.',
     '''The white bishops have distinct jobs: d6 helps constrain the king, while g8 can later travel down a long diagonal. Black's knight h6 blocks the h-file. White's queen f6 is close to the king c6, but closeness alone does not provide the required move. Look for a queen square that becomes useful when the h6 knight moves, and then separately account for the king's legal escape to b7.''',
     '''Qh8 is the key. The queen is placed at the top of the h-file, behind the black knight's current obstruction on h6. Every legal move of that knight clears the file, making Qh1 possible. From h1 the queen checks the king c6 along the diagonal h1–g2–f3–e4–d5–c6. This is a change of direction: first the queen uses a vertical route, then her final attack is diagonal. Knowing which line is a travel route and which gives check prevents a misleading explanation.''',
     '''The knight may play Nxg8, Nf7, Nf5, or Ng4. Even Nxg8, which captures White's bishop, permits Qh1 mate because it clears h6 just like the other knight moves. Black's only king move is Kb7. Here the bishop on g8 remains alive, and it goes to d5 with mate along d5–c6–b7. White does not try to preserve the bishop in the knight-capture branch; it is needed only in the different branch where the king moves.''',
     '''Replay Nxg8 and trace the queen's journey all the way down the h-file before following its checking diagonal. Then reset and choose Kb7, moving the bishop from g8 rather than the bishop on d6. Explain why a bishop on d6 cannot move straight down to d5. Finally compare Qe5, which fails against Kb7. The lesson is to identify the exact attacker and exact route in each branch, especially when two same-color pieces make a verbal description ambiguous.''',
     'Qh8 waits for the h6 knight to clear the h-file and preserves a bishop mate against Kb7.',
     [('Nxg8','Qh1#','The knight captures the g8 bishop and vacates h6.','The queen travels down the now-clear h-file, then checks c6 diagonally from h1.'),
      ('Kb7','Bd5#','Black chooses the king move, leaving the g8 bishop on the board.','That bishop travels g8–f7–e6–d5 and checks b7 along the diagonal.')],
     [('After Qh1, which line actually checks the black king?', 'The diagonal h1–g2–f3–e4–d5–c6', 'The h-file is the queen’s travel route, not the final checking line.', 'The h-file', 'The black king is on c6, not on the h-file.'),
      ('Which bishop mates on d5 after Kb7?', 'The bishop from g8', 'g8–f7–e6–d5 is a legal diagonal.', 'The bishop from d6', 'A bishop cannot move vertically from d6 to d5.')],
     ('Separate travel route from checking line.', 'A knight move clears h6.', 'Name the bishop’s starting square.'))

_add(7, 'A double pawn move keeps the king sheltered',
     'Babson’s a4 preserves a shield on the a-file while letting the queen and rooks answer Black’s rook moves.',
     '''The white king a8 is unusually far up the board, with its queen a6 below it on the same file. Black's rook a1 could become dangerous if the obstructions on that file disappeared. The white pawn a2 may legally advance two squares because it is on its starting rank and both a3 and a4 are empty. Do not assume that an artificial position removes the ordinary pawn rules. Those rules are part of the solution.''',
     '''The key is a4, not a3. The pawn's placement on a4 preserves an a-file shield when White's queen leaves a6 in several variations. The tempting a3 allows the e3 rook to capture it with Rexa3. Then a queen departure can expose the white king along the a-file, so the expected mating move is no longer available. A two-move problem still requires White's own king to be safe after every move; the attacking idea cannot excuse an illegal self-check.''',
     '''Black's two rooks have many moves, but their roles organize the answer. Moves of the e3 rook along the third rank commonly permit Qe2; moves along the e-file can allow Qd3. A rook occupying d3 or e2 is captured by the corresponding queen mate. Moves of the a1 rook up the a-file are met by Rb1, while Rc1 is answered by Rd2 and Rb1 by Rxb1. The notation Rea3 and Raa3 distinguishes which rook moved to a3, and the correct mating response differs.''',
     '''Study those two a3 branches side by side. After Rea3 use Qe2; after Raa3 use Rb1. The same destination does not produce the same board because the other rook remains on a different square. Then replace the key with a3 and inspect Rexa3 to see the missing shield. This problem teaches three practical habits together: keep your own king safe, distinguish identical pieces by origin, and justify the length of a pawn advance with the resulting lines.''',
     'a4 makes the legal initial double push and preserves a useful shield on the a-file.',
     [('Rea3','Qe2#','The e3 rook moves to a3; the pawn a4 remains between it and the white king.','The queen can safely leave a6 and check d1 diagonally from e2.'),
      ('Raa3','Rb1#','This time the a1 rook moves to a3 and the other rook stays on e3.','The b2 rook checks along the first rank from b1.'),
      ('Rc1','Rd2#','The a1 rook moves along the first rank to c1.','The c2 rook reaches d2 and gives an adjacent file check.'),
      ('Re1','Qd3#','The e3 rook drops to e1.','The queen reaches d3 and checks down the d-file.')],
     [('Why is a2–a4 legal in this composition?', 'The pawn starts on rank 2 and both intervening squares are clear', 'Compositions use the ordinary movement rules.', 'Problem pawns may always move two squares', 'A pawn away from its starting rank cannot make an initial double push.'),
      ('Do Rea3 and Raa3 lead to identical positions?', 'No; they move different rooks and leave the other rook elsewhere', 'Their mating answers therefore need separate checking.', 'Yes; only the destination matters', 'The origin determines which lines and defences remain.')],
     ('Keep the a-file shield.', 'Compare a4 with a3 concretely.', 'Track the origin of each rook.'))

_add(8, 'Offer the queen to control a discovered attack',
     'Maksimov’s Qg3 makes the f-pawn’s departure powerful while answering two different captures of the queen.',
     '''The bishop g1 points toward the black king c5 along g1–f2–e3–d4–c5, but White's own pawn f2 blocks that diagonal. Moving the pawn could uncover a check. Black's rook g4, however, has access toward g1, so merely opening the diagonal is not enough. Also notice that Black's pawn f4 prevents White's pawn from immediately advancing two squares. The task is to coordinate a discovered attack with the defender's available captures.''',
     '''Qg3 offers the queen on a square between the rook g4 and the bishop g1. Black cannot simply move that rook through the queen to capture the bishop. If the rook captures the queen on g3 instead, White's f-pawn can capture the rook and open the bishop's diagonal at the same time. If Black's f4 pawn captures the queen, f4 becomes empty and White can use a two-square pawn advance. The queen's apparent exposure changes both the defensive route and the pawn's choices.''',
     '''After Rxg3+, play fxg3 mate. White answers the rook's check by capturing it, and moving the f-pawn uncovers the bishop's check. After fxg3, play f4 mate; the black pawn has vacated f4, making that advance legal. Many other moves allow f3 mate, again opening the bishop. There are two useful exceptions: Kd4 is met by Qc3, and f3 by Qd6. In the latter case Black's pawn occupies f3, so White must change attacking pieces.''',
     '''Replay both queen captures and name which pawn moved on each turn. In fxg3 by Black, the pawn starts on f4; in fxg3 by White, it starts on f2. Then try the premature f3+: Black can answer Rxg1 and remove the checking bishop. The key's purpose becomes clearer when you see that concrete failure. A discovered check is valuable only if the newly opened attacker cannot simply be captured or the check otherwise answered.''',
     'Qg3 interrupts the rook’s route to g1 and offers a queen sacrifice that activates the f-pawn.',
     [('Rxg3+','fxg3#','The g4 rook captures the queen and checks along the third rank.','The f2 pawn captures that rook, answering check and uncovering the bishop g1.'),
      ('fxg3','f4#','Black’s f4 pawn captures the queen, leaving f4 empty.','The f2 pawn advances two squares and uncovers the bishop’s mating diagonal.'),
      ('f3','Qd6#','Black advances its pawn to f3, blocking White’s usual pawn move.','The queen changes the mechanism and checks c5 from d6.'),
      ('Kd4','Qc3#','The king moves to d4.','The queen checks from c3 with the remaining pieces closing the exits.')],
     [('What gives check after White’s fxg3?', 'The bishop on g1, through the vacated f2 square', 'The pawn move uncovers the long diagonal.', 'The pawn on g3 directly attacks c5', 'A pawn on g3 attacks f4 and h4, not c5.'),
      ('Why is f4 possible after Black’s fxg3?', 'Black’s pawn has vacated f4', 'White can then make the initial two-square advance from f2.', 'The pawn may jump over an occupied destination', 'Both the intermediate and destination squares must be clear.')],
     ('Find the blocked bishop.', 'Distinguish the two fxg3 captures.', 'A queen sacrifice can protect an attacking line.'))

_add(9, 'Make a discovered check answer the rook’s defence',
     'Khokholous’s Bc7 clears one part of the h-file and prepares bishop interpositions against Black’s rook.',
     '''The queen h8 and black king h1 share a file, but White's bishops on h7 and h2 interrupt that line twice. The rook a1 and king f1 form another potential discovered attack along the first rank. Black's rook a8 can capture, move across the eighth rank, or descend the a-file. This is a problem about opening a checking line while also stopping whatever defensive line Black has just created.''',
     '''Bc7 moves the h2 bishop away from the h-file and leaves the h7 bishop as the remaining blocker of the queen's attack. A later move by that bishop can uncover check. The square c7 also gives the moved bishop useful control toward h2, helping constrain the black king. Black's rook can choose different ranks, so the h7 bishop often has to land on precisely the right square to obstruct that rook at the same time as it vacates the h-file.''',
     '''After Rxa1+, White must answer check on the first rank. Bb1 does that by interposing on b1, and simultaneously opens the queen's h-file mate. After Ra2, Bc2 cuts the rook's second-rank route while uncovering the same check. Ra4 is met by Be4, Ra5 by Bf5, and Ra6 by Bg6. If the rook instead captures the queen with Rxh8, Kf2 uncovers a different mating line: the white rook a1 checks along the first rank once its own king moves away.''',
     '''Do not label every bishop departure a solution. Choose Black's rook move first, then find a destination that both opens the h-file and stops the rook's possible interference. In the capture-on-a1 branch, explicitly verify that the white king's check has been answered. Finally replay Rxh8 to see why losing the queen does not end the attack. The practical pattern is a move doing two jobs at once: uncovering your check and meeting the opponent's concrete defensive threat.''',
     'Bc7 clears h2 and prepares a discovered queen check when the h7 bishop moves.',
     [('Rxa1+','Bb1#','The rook captures a1 and checks White’s king along the first rank.','Bh7–b1 blocks that check and uncovers the queen’s mate down the h-file.'),
      ('Ra2','Bc2#','The rook descends to the second rank.','The bishop cuts the second rank on c2 and opens the h-file check.'),
      ('Ra6','Bg6#','The rook chooses the sixth rank.','The bishop blocks that rank on g6 while vacating h7.'),
      ('Rxh8','Kf2#','The rook captures the queen on h8.','The white king moves off f1, uncovering the rook a1’s mating line to h1.')],
     [('Why does Bb1 work after Rxa1+?', 'It blocks Black’s check and uncovers White’s queen check', 'Both king-safety requirements are met by one bishop move.', 'White may ignore check when attacking', 'A mating move must still leave White’s king safe.'),
      ('What gives mate after Rxh8 Kf2?', 'The white rook on a1', 'Moving the king off f1 opens the first rank.', 'The captured queen on h8', 'That queen has left the board.')],
     ('Open one line while blocking another.', 'Answer every checking defence.', 'Look for the second discovered attack.'))

_add(10, 'Retreat a bishop to prepare several different mates',
     'Galitsky’s Ba4 lets Black capture the central rook, yet prepares a different bishop mate for each capturer.',
     '''White's rook e4 is available to both the black king f3 and bishop c2. The white bishop c6, queen d6, and knight c4 form the rest of the attack. Black's knights on b1 and e6 guard different potential mating squares. Begin by identifying those jobs separately. The king's capture of the rook and the bishop's capture of the same rook produce different positions, so they cannot be analyzed as one generic acceptance.''',
     '''Ba4 retreats the bishop along c6–b5–a4. After Kxe4, the bishop returns to c6 with mate, now checking the king on its new square e4. After Bxe4, the bishop instead travels from a4 to d1, using the diagonal a4–b3–c2–d1 that Black's bishop has just cleared. The first move therefore prepares two diagonal routes. Moving backward is useful because it supplies the correct angle of approach for a later check, not because retreat has a special value by itself.''',
     '''The rest of Black's army explains the other finishes. Moving the b1 knight usually permits Nd2; if it moves to d2, White captures it there. Moving the e6 knight generally permits Qf4, with Qxf4 if the knight occupies f4. Bishop departures that leave the king on f3 commonly permit Qd3. Finally, hxg4 is answered by Re3. Use these groups to organize the many replies, but verify the individual capture squares rather than copying a move without checking the new board.''',
     '''Play Kxe4 and Bxe4 on separate boards or reset between them. Name the black piece now on e4, the bishop that moves for White, and the final checking diagonal. Then choose a knight defence and identify the square it stopped guarding. Compare the immediate Qd3+ with the prepared solution: Black can simply answer Bxd3. The lesson is to arrange the opponent's changes in advance instead of demanding that a familiar-looking check work before its defender has been dealt with.''',
     'Ba4 prepares either a return to c6 or a new diagonal toward d1 after the rook is captured.',
     [('Kxe4','Bc6#','The king captures the rook on e4.','The bishop returns a4–b5–c6 and checks e4 along c6–d5–e4.'),
      ('Bxe4','Bd1#','The c2 bishop captures the rook, clearing c2.','The white bishop uses a4–b3–c2–d1 and checks f3 diagonally.'),
      ('Nf4','Qxf4#','The e6 knight moves onto the queen’s mating square.','The queen captures it on f4 with mate.'),
      ('hxg4','Re3#','The h5 pawn captures White’s pawn on g4.','The rook checks the king f3 from e3, with the exits covered.')],
     [('Why does Bxe4 allow Bd1?', 'The black bishop has vacated c2', 'c2 lies on the white bishop’s route a4–b3–c2–d1.', 'The white bishop may jump over c2', 'Bishops cannot jump over an occupied square.'),
      ('After Kxe4, which square does White’s bishop use?', 'c6', 'From c6 it checks the king e4 diagonally.', 'e4', 'That square is occupied by the black king, which is never captured.')],
     ('Separate king capture from bishop capture.', 'A retreat can prepare a better diagonal.', 'Group knight defences by the guard they abandon.'))
_add(11, 'Let the pawn promote, then choose the right mate',
     'Shinkman’s Rf1 permits promotion while keeping a mating answer to every promoted piece and every knight defence.',
     '''Black's pawn e2 is one step from promotion, but the rook e1 currently stands directly in front of it. The pawn also lies on the white queen's second-rank route from f2 toward b2. White must move with more precision than simply capturing that pawn. The crowded king e5 is the real target, and a promotion may clear a useful line for White even while giving Black a powerful new piece.''',
     '''Rf1 clears e1 and offers the rook to exf1. If Black captures on f1 and promotes, the e2 square becomes empty, allowing Qb2 mate along b2–c3–d4–e5. Promotion is compulsory on the last rank, but Black may choose a queen, rook, bishop, or knight. The mating answer works after all four capturing promotions. Thus the point is the pawn's departure from e2 and the promoted piece's exact square, not a belief that Black will automatically choose a queen.''',
     '''Black can also promote straight ahead on e1 without taking the rook. Rxe1 is mate after any of those four choices: White captures the newly promoted piece and checks along the e-file. Some underpromotions permit additional queen mates, but that does not change the reliable answer. The knight h5 supplies further defences: Nf4 is met by Qxf4, while moves such as Nf6 allow Qf4. The pawn move d2 allows Qe3. These replies must be checked as seriously as the spectacular promotion.''',
     '''Practise the two promotion destinations separately. On f1 the promoted piece has captured the rook, so White must use the queen; on e1 the rook remains available to capture it. Say the full notation, including the chosen promotion piece, before playing the reply. Compare the immediate Rxe2+: Black answers dxe2, so taking the dangerous pawn at once does not solve the task. Precise geometry can matter more than the apparent value of the piece Black is about to gain.''',
     'Rf1 clears the promotion square e1 and offers the rook on f1 while preparing mates against both choices.',
     [('exf1=Q','Qb2#','The pawn captures the rook and promotes to a queen on f1.','With e2 clear, the queen reaches b2 and checks e5 along the diagonal.'),
      ('exf1=N','Qb2#','Black chooses a knight instead after the same capture.','The same queen mate works; underpromotion does not escape the net.'),
      ('e1=Q','Rxe1#','Black promotes on e1 without capturing the rook.','The rook captures the new queen and checks up the e-file.'),
      ('Nf4','Qxf4#','The knight moves to f4 instead of promoting a pawn.','White captures that knight with the mating queen.')],
     [('Does the f1 capture branch require Black to promote to a queen?', 'No; Qb2 mates after all four promotions', 'The cleared e2 square is the essential change.', 'Yes; a knight promotion refutes it', 'The knight on f1 cannot prevent Qb2 mate.'),
      ('After e1=Q, where is White’s rook?', 'Still on f1, ready to play Rxe1', 'The pawn advanced straight and did not capture it.', 'Captured and removed from the board', 'That happens after exf1, not after e1.')],
     ('Track the promotion destination.', 'Check every promotion choice.', 'Clearing e2 can be more important than gaining a queen.'))

_add(12, 'Promote to the piece that actually checks',
     'Gottschall’s bishop offer produces a knight promotion mate when Black’s pawn accepts it.',
     '''White's pawn g7 is almost promoted, but the strongest new piece by material value is not automatically the right piece. The black king f6 is a knight's move away from g8. White's knight f7, king h7, and queen b3 restrict the surrounding squares. The bishop e4 can change the black pawn's position or draw the king onto another square. First identify the checking pattern you would need after a promotion, before choosing the promotion piece.''',
     '''The key Bf5 offers the bishop both to the king f6 and to the pawn e6. If the pawn captures with exf5, g8=N is mate: the promoted knight directly attacks f6. A queen on g8 does not make that same knight-shaped attack, so automatic queen promotion misses the point. The other pieces do not disappear from the explanation. They control the king's escape squares while the new knight delivers the final check and covers additional flights such as e7.''',
     '''If the king accepts the bishop with Kxf5, White mates with Qf3. If the king moves to e7 or captures the knight on f7, Qxe6 is mate. If Black instead advances the pawn to e5, Qe6 is mate without a capture on e6. The difference between Qe6 and Qxe6 records whether the pawn stayed on e6 or left it. All five legal replies are accounted for, so the attractive underpromotion is one branch of a complete solution, not a trick that requires cooperation.''',
     '''Replay exf5 and stop before promoting. Compare the actual attacks from a queen on g8 with those from a knight on g8. Then choose the knight and inspect the final king flights. Next replay a king capture branch to make sure you can still solve the position when Black declines the pawn capture. In ordinary games, the same habit is useful: ask what the promoted piece must do immediately. Material value matters less than the required check, fork, defensive coverage, or avoidance of stalemate.''',
     'Bf5 offers the bishop and prepares a distinct mating answer for each way Black responds.',
     [('exf5','g8=N#','The e6 pawn captures the bishop on f5.','Promote to a knight: from g8 it checks the king f6 and completes the net.'),
      ('Kxf5','Qf3#','The king captures the bishop itself.','The queen checks up the f-file from f3.'),
      ('Kxf7','Qxe6#','The king captures White’s original knight on f7.','The queen captures the e6 pawn and checks f7 diagonally.'),
      ('e5','Qe6#','The pawn advances from e6 to e5.','The queen reaches the now-empty e6 square with mate.')],
     [('Why promote to a knight after exf5?', 'A knight on g8 directly checks f6', 'The attack required here has a knight’s shape.', 'A queen is forbidden in compositions', 'Queen promotion is legal; it simply does not provide this mate.'),
      ('Why does the e5 branch use Qe6 rather than Qxe6?', 'The black pawn has left e6', 'The queen moves to an empty square.', 'Captures cannot be checkmate', 'Captures can certainly mate; this move is not a capture.')],
     ('Choose a promotion by its job.', 'The knight must actually check.', 'Distinguish pawn capture from king capture.'))

_add(13, 'One knight move unlocks several discovered checks',
     'Loyd’s Nf2 prepares a knight mate, a rook discovery, and a queen discovery according to where Black’s king goes.',
     '''The white knight g4 can move to f2 while the other white knight stays on f6. White's rook f1 and queen e1 stand behind that destination, so a later departure from f2 may open either a file or a diagonal. Black's pawn h3 is a possible target, and the king g5 has several directions to consider. This is a good position for separating the piece that moves from the piece that actually gives check.''',
     '''Nf2 prepares Nxh3. If the black king stays on g5, the knight on h3 itself gives check. If the king moves onto the f-file, the same knight departure from f2 can instead uncover the rook f1's check. Black may even capture the other knight with Kxf6; Nxh3 still works because the rook's file has become clear. A sacrifice is only part of the idea. The more useful lesson is that the same final move can check in different ways after different king moves.''',
     '''The special king flight Kh4 needs a different finish: N2e4. The knight from f2 moves away, opening the queen's diagonal e1–f2–g3–h4, while its new square contributes to the net. The notation includes 2 because both white knights could legally move to e4; this solution requires the one from rank 2. If Black pushes h2, the finish is Nh3 without a capture. The numerous black knight moves all leave Nxh3 available. Do not memorize the capture sign independently of the pawn's location.''',
     '''Replay Kxf6 and identify the rook as the final checker. Then replay Kh4 and identify the queen instead. Finally use a black knight move and see that the knight on h3 gives the check itself. Keep these three mechanisms separate in your explanation. When notation is ambiguous, locate the starting square before moving. This avoids a common beginner mistake: moving the right type of piece to the right destination but choosing the wrong piece and leaving the intended checking line blocked.''',
     'Ng4–f2 prepares a departure that can open either the rook’s file or the queen’s diagonal.',
     [('Kxf6','Nxh3#','The king captures White’s knight on f6.','The remaining knight leaves f2 and captures h3, uncovering the rook f1’s check.'),
      ('Kh4','N2e4#','The king moves to h4.','The f2 knight moves to e4; the queen e1 now checks along e1–f2–g3–h4.'),
      ('Ne8','Nxh3#','The d6 knight moves while the black king stays on g5.','Here the knight on h3 itself checks g5.'),
      ('h2','Nh3#','The pawn moves from h3 to h2.','The knight lands on empty h3 and gives mate, so there is no capture sign.')],
     [('After Kxf6 Nxh3, which piece gives check?', 'The rook on f1', 'Moving the f2 knight clears the f-file to the king on f6.', 'The knight on h3', 'A knight on h3 does not attack f6.'),
      ('What does the 2 in N2e4 specify?', 'Move the knight from rank 2', 'The knight on f2 must clear the queen’s diagonal.', 'Move both knights to e4', 'Only one piece moves on a normal turn.')],
     ('Identify the actual checker.', 'Follow the file and the diagonal separately.', 'Read disambiguating notation carefully.'))

_add(14, 'Give the king two moves, then mate with one pawn',
     'Chinn’s Kg7 deliberately releases two king flights that are both answered by f4 mate.',
     '''Black has only a king, so a move that leaves it without a legal move and without check would stalemate. White has ample force but must use it with care. The white king h6 protects the knight g5. Meanwhile the bishop h8 looks down the diagonal through g7 and f6 toward e5. Those two white controls help explain why an apparently helpful move can accidentally leave Black with no turn to play.''',
     '''Kg7 changes two controls at once. By leaving h6, the white king stops protecting g5, so Black may capture the knight with Kxg5. By arriving on g7, the king blocks its own bishop's diagonal from h8 toward e5, making Ke5 available too. This is deliberate interference with a friendly piece. White is not trying to maximize the number of attacked squares immediately. The aim is to give Black exactly the changes that allow a mating move on the following turn.''',
     '''Black has precisely two legal replies after the key: Kxg5 and Ke5. Both are met by f4 mate. A white pawn on f4 attacks g5 and e5, so the same pawn move directly checks either king destination. The remaining pieces close the surrounding squares, and the rook f1 supports the pawn along the f-file after f3 is vacated. There is no need to imagine a hidden queen or a special rule. Ordinary pawn attacks provide the common finish.''',
     '''Play both king replies and verify the pawn's two capture directions. Then reset and try the plausible alternatives Nf7 or Kg6. Each leaves Black stalemated rather than producing the required mate in two. This contrast is valuable in your own games: more restriction is not always better when the defender has very few moves. Before a quiet move against a lone king, ask whether the opponent will still have a legal move and whether the next check will actually be available.''',
     'Kg7 releases g5 by leaving h6 and releases e5 by blocking the h8 bishop’s diagonal.',
     [('Kxg5','f4#','The king captures the now-unprotected knight on g5.','The f3 pawn advances to f4 and checks g5 directly.'),
      ('Ke5','f4#','The king enters e5, now released by the obstruction on g7.','The same pawn move checks e5, the pawn’s other attacking square.')],
     [('Why can Black play Ke5 after Kg7?', 'White’s king blocks the h8 bishop on g7', 'The bishop no longer attacks e5 through that square.', 'Kings may enter bishop attacks in problems', 'All ordinary king-safety rules still apply.'),
      ('Which squares does a white pawn on f4 attack?', 'e5 and g5', 'Those are exactly the two black king destinations.', 'e3 and g3', 'Those would be the attacking directions of a black pawn on f4.')],
     ('Count legal moves to avoid stalemate.', 'A friendly obstruction can be purposeful.', 'One pawn can check either of two king squares.'))

_add(15, 'Release exactly one capture',
     'Wormall’s Qh1 stops guarding b6, giving Black the only legal move Kxb6 and allowing Nc4 mate.',
     '''The black king a5 has a wall of pieces and pawns around it, and Black's pawns cannot simply advance. In particular, the pawn b7 is blocked by White's pawn b6, the pawn d6 by d5, and the pawn g3 by g2. The white queen g1 guards b6 along g1–f2–e3–d4–c5–b6. That long diagonal helps immobilize Black, but complete immobilization without check is not the goal.''',
     '''Qh1 removes the queen's protection of b6. The king can now capture the pawn there, while the other restrictions stay sufficient to leave no alternative legal move. The key is therefore an act of permission: White offers a pawn and lets the king enter the precise square needed for the final knight check. The queen's destination must be judged by the whole reply set. A move that merely appears to wait may retain the old stalemate or give Black a different useful move.''',
     '''After Qh1, Black must play Kxb6; there is exactly one legal reply. White then plays Nc4 mate with the knight from b2. On c4 that knight attacks b6 directly, and White's remaining king, bishop, knight, and pawns supply the necessary restrictions. The pawn b6 has served as bait and is no longer on the board. Make that removal explicit when you inspect the final position; forgetting captured pawns can make a correct mating net look falsely overcrowded.''',
     '''Reset and trace the queen's original diagonal to b6. Move her to h1, then verify that Kxb6 has become legal before playing the knight mate. Compare Qd4: the queen still guards b6, and Black is stalemated. Compare Qf2: Black has the alternative gxf2, which spoils the two-move task. The transferable lesson is to control the opponent's choices with exact squares, while remembering that the defender must be allowed a legal move if your plan needs a second turn.''',
     'Qh1 stops guarding b6 and gives Black exactly one legal move.',
     [('Kxb6','Nc4#','The king captures the offered b6 pawn; every other Black move is unavailable.','The b2 knight moves to c4 and attacks b6 with mate.')],
     [('Which protection does Qh1 remove?', 'The queen’s diagonal protection of b6', 'That makes the king’s capture Kxb6 legal.', 'The knight’s protection of a4', 'The queen move does not change the b2 knight’s attacks.'),
      ('Why does Qd4 fail as a waiting move?', 'It leaves Black stalemated', 'The queen still prevents the needed Kxb6.', 'A queen may not move on a diagonal', 'Diagonal movement is legal; the resulting move availability is the issue.')],
     ('Release b6 deliberately.', 'Distinguish forced movement from stalemate.', 'Use the b2 knight for the final check.'))

_add(16, 'Clear the bishop’s path with a queen sacrifice',
     'Grimshaw’s Qg8 vacates c4 so the bishop b3 can use d5, even if Black captures the queen or rook.',
     '''The bishop b3 wants to travel through c4 to d5, but White's queen currently blocks c4. From d5 the bishop would check the black king b7 along d5–c6–b7. White's rook a8 is also available to the black king. The problem asks for more than simply moving the queen somewhere: her destination must leave the bishop route useful against all the possible black replies, including a king flight toward the centre.''',
     '''Qg8 clears c4 and sends the queen to the far end of the bishop's diagonal. The important clearance is behind her: b3–c4–d5 is now open. Black may capture the queen with either Rxg8 or Qxg8, but the bishop mate remains. The king can even capture the rook on a8; Bd5 then checks along the extended diagonal d5–c6–b7–a8. White is willing to lose substantial material because the cleared bishop route ends the game before those gains can matter.''',
     '''Most of Black's twenty-four replies are answered by Bd5. The significant king-flight exception is Kc6, when Ba4 is mate instead. From a4 the bishop checks along a4–b5–c6 and controls the continuation of that diagonal. Some other replies permit extra finishes, but those are not needed to understand the key. The source's phrase about clearing a path refers to an actual occupied square, c4, and an actual bishop journey; it is not merely a general statement about becoming active.''',
     '''Start with Rxg8 and follow the bishop from b3 through the vacated c4 square. Next use Kxa8 and extend the same checking diagonal one square farther. Finally choose Kc6 and find Ba4 rather than repeating Bd5 automatically. Compare the immediate Ba4+: Black can capture the rook with Kxa8, and White has no mate on the next move. This shows why recognizing a useful bishop square is only part of solving the whole position.''',
     'Qg8 clears c4, opening the b3 bishop’s route to d5.',
     [('Rxg8','Bd5#','The h8 rook captures the queen on g8.','The b3 bishop passes through c4 to d5 and checks b7 diagonally.'),
      ('Qxg8','Bd5#','The queen h7 captures White’s queen instead.','The same cleared bishop route still produces mate.'),
      ('Kxa8','Bd5#','The king captures White’s rook on a8.','The diagonal from d5 extends through c6 and b7 to the king on a8.'),
      ('Kc6','Ba4#','The king chooses the central flight c6.','Use a4: the bishop checks along a4–b5–c6 with the exits closed.')],
     [('Which square must the queen clear for Bd5?', 'c4', 'It lies between the bishop on b3 and d5.', 'f7', 'f7 is farther along the diagonal and does not obstruct b3–d5.'),
      ('After Kc6, should White repeat Bd5 automatically?', 'No; the mating finish is Ba4', 'The changed king square requires the other bishop route.', 'Yes; one threat must answer every king move', 'A sound key may need different finishes against different defences.')],
     ('Name the obstructing square.', 'Calculate captures of both queen and rook.', 'Keep the Kc6 exception separate.'))

_add(17, 'Choose where to block the remaining defender',
     'Hartong’s Qb2 offers the queen to rook or bishop, then uses Rd2 or Rd4 to obstruct the defender left behind.',
     '''The bishop h2 points toward the black king c7 along h2–g3–f4–e5–d6–c7, but White's rook d6 blocks the line. Moving that rook can uncover check. Black's rook b4 and bishop c1 can interfere on different parts of the bishop's checking diagonal. The initial question is therefore not just how to move the rook away, but where it must land to prevent the remaining black defender from blocking the discovered check.''',
     '''Qb2 offers the queen to both defenders. If the rook captures with Rxb2, Black's bishop remains on c1, so White plays Rd2. The rook leaves d6 to open the bishop's check and blocks the c1 bishop's diagonal through d2 toward f4. If the bishop captures with Bxb2, Black's rook remains on b4, so White plays Rd4 instead. This blocks its fourth-rank route toward f4 while again opening the h2 bishop's line. The same white rook performs clearance and obstruction in one move.''',
     '''These two captures are the central comparison, but Black is free to decline them. Many rook or pawn moves permit Qg7, while other rook placements call for Qb6 or a capture on b7. In the important Rxb7 branch, Qxb7 is mate. The complete reply map includes all eighteen legal defences. Do not conclude that the queen sacrifice forces acceptance; its strength is that each acceptance damages the defence in a useful way and the non-capturing moves also have answers.''',
     '''Play Rxb2 and point to the black bishop c1 before choosing Rd2. Then reset, play Bxb2, and point to the black rook b4 before choosing Rd4. In both final positions, the bishop h2 gives check; the rook's destination controls a potential defensive route. Explaining those separate jobs is more useful than memorizing the two rook squares. In practical tactics, a discovered check often succeeds only after the moving piece also prevents a block, capture, or counter-check.''',
     'Qb2 offers the queen to either defender and lets White tailor the rook’s blocking square.',
     [('Rxb2','Rd2#','The rook captures the queen, leaving Black’s bishop on c1.','Rd2 clears the h2 bishop’s check and blocks the c1 bishop’s route toward f4.'),
      ('Bxb2','Rd4#','The bishop captures the queen, leaving Black’s rook on b4.','Rd4 clears the same check and cuts the b4 rook’s route along the fourth rank.'),
      ('Rxb7','Qxb7#','The rook captures White’s bishop on b7 instead of taking the queen.','The queen captures that rook on b7 with mate.')],
     [('After Rxb2 Rd2, which white piece gives check?', 'The bishop on h2', 'Moving the rook off d6 uncovers the long diagonal.', 'The rook on d2', 'd2 is neither on the c7 king’s file nor rank.'),
      ('Why use Rd4 after Bxb2?', 'It blocks the remaining rook’s fourth-rank route', 'The black rook b4 must be prevented from reaching f4.', 'The rook must always copy the bishop’s destination', 'The destination follows the remaining defender’s line, not a copying rule.')],
     ('Identify the defender left behind.', 'Clear the bishop’s check.', 'Block the remaining defensive route.'))

_add(18, 'Return the queen after the king changes squares',
     'Guliaev’s Qf1 releases a bishop capture and prepares three clean finishes against the black king’s three moves.',
     '''Black has only a king on d6, surrounded by White's queen, two bishops, and two knights. White's queen a6 currently protects the bishop c6 across the sixth rank. The knight c7 and king c8 restrict moves near the top of the board. Instead of assuming that every attacked piece must remain protected, examine what would happen if the king were permitted to capture c6 and thereby step onto the queen's future checking line.''',
     '''Qf1 is the quiet key. The queen leaves a6 along the diagonal a6–b5–c4–d3–e2–f1 and releases the capture Kxc6. After that capture, Qa6 is mate: the queen returns to her original square, but the black king is now on c6, so the sixth-rank line has become a check. A return move is not wasted time when the opponent's intervening move has changed its effect. The black king's two other choices are handled by the bishop f2.''',
     '''Black has exactly three legal replies. Kxc6 is met by Qa6; Ke7 by Bc5; and Ke5 by Bg3. In the latter two branches, the bishop from f2 uses different diagonals to reach a checking square. Bc5 checks e7 through d6, while Bg3 checks e5 through f4. The remaining white forces close the exits. Because Black has no other pieces, you can verify the complete reply set by checking each neighboring king square against White's attacks.''',
     '''Play the queen-return branch first and compare the initial board with the final board. The queen occupies a6 in both, but the bishop c6 has been captured and the black king has moved from d6 to c6. Then practise the two bishop mates without moving the wrong bishop: they both use the bishop that began on f2. This composition teaches you to evaluate a move in its current position, rather than judge a return to an earlier square as automatically pointless.''',
     'Qf1 releases Kxc6 while preparing two bishop mates against the other king moves.',
     [('Kxc6','Qa6#','The king captures the bishop c6, now no longer protected by the queen.','The queen returns to a6 and checks the king across the sixth rank.'),
      ('Ke7','Bc5#','The king steps to e7.','The f2 bishop moves through e3 and d4 to c5, checking e7 along c5–d6–e7.'),
      ('Ke5','Bg3#','The king steps to e5 instead.','The same f2 bishop reaches g3 and checks e5 through f4.')],
     [('Why can Qa6 mate even though the queen began there?', 'Black’s king has moved to c6 in between', 'The changed king square makes the sixth-rank attack a check.', 'Returning moves have special power in problems', 'There is no special rule; the board position changed.'),
      ('Which bishop plays both Bc5 and Bg3 in the alternative branches?', 'The bishop on f2', 'Both destinations lie on legal routes from f2.', 'The bishop on c6', 'The c6 bishop does not have either required route.')],
     ('A return move can exploit a changed board.', 'Count the king’s three legal replies.', 'Use the f2 bishop in both side branches.'))

_add(19, 'Advance the pawn one square or two to stop interference',
     'Kubbel’s Ne8 prepares a discovered bishop mate in which c3 and c4 are chosen according to the black rook’s rank.',
     '''The bishop b1 points toward the black king f5 along b1–c2–d3–e4–f5, but White's pawn c2 blocks it. Advancing that pawn could uncover check. Black has rooks on both f3 and f4, however, and either may be able to block the new bishop line from its own rank. White's knight f6 also contributes important controls. Start by identifying the two interference squares d3 and e4, because they explain the most memorable variations.''',
     '''Ne8 moves the f6 knight back to the eighth rank and arranges the complete set of answers. If the f4 rook goes to a4, White plays c4 mate: the pawn leaves c2 to open the bishop, and on c4 it cuts the rook's fourth-rank route toward e4. If the f3 rook goes to a3, White instead plays c3 mate, cutting that rook's third-rank route toward d3. The length of the pawn advance is determined by the defender's line, not by a general preference for gaining more space.''',
     '''Most other replies are answered by Qxe6, capturing the pawn and checking the king. There are important additional cases: e5 allows Nd6, Re4 allows Ng7, and Re3 allows Rxf4. In that last branch the f3 rook has left the f-file, enabling White's rook f1 to capture the remaining rook on f4 and check the king f5. The key also allows Ke4, but Qxe6 still mates, now along the e-file. The varied finishes make it essential to update both the king square and the rook positions.''',
     '''Replay Ra4 c4 and Ra3 c3 side by side. Try exchanging the two pawn answers and locate the newly available black block. Then choose one of the special rook or pawn defences and identify the actual final checker. This is a practical lesson in combining two tasks: your pawn clears its own bishop's line while obstructing the opponent's line. A move that does only the first job can look like a winning discovered check and still allow a straightforward defensive interposition.''',
     'Ne8 prepares the pawn discoveries and keeps a mating reply to the king, rook, bishop, and pawn defences.',
     [('Ra4','c4#','The f4 rook moves to a4.','The two-square pawn advance opens bishop b1 and blocks the rook’s fourth-rank route to e4.'),
      ('Ra3','c3#','The f3 rook moves to a3 instead.','The one-square pawn advance opens the bishop and blocks the third-rank route to d3.'),
      ('Re3','Rxf4#','The f3 rook leaves the f-file for e3.','The white rook f1 captures the remaining f4 rook and checks f5.'),
      ('e5','Nd6#','The pawn advances to e5.','The e8 knight jumps to d6 and checks f5 while controlling key flights.')],
     [('Why use c4 after Ra4?', 'The pawn cuts the rook’s fourth-rank route toward e4', 'It also vacates c2 to uncover bishop b1.', 'A two-square pawn move is always stronger', 'After Ra3 the required blocking rank is rank 3 instead.'),
      ('What gives check after Ra3 c3?', 'The bishop on b1', 'The pawn’s departure opens b1–c2–d3–e4–f5.', 'The pawn on c3 directly attacks f5', 'A white pawn on c3 attacks b4 and d4.')],
     ('Match the pawn’s rank to the rook’s rank.', 'Open your line and obstruct theirs.', 'Keep the special defences separate.'))

_add(20, 'Choose the exact knight departure for each defence',
     'Isaev’s Qf6 makes three different knight moves necessary: they preserve a pin, block a queen route, or protect c5.',
     '''White's knight b4 blocks two possible discovered attacks: the rook b1 toward the black king b5, and the bishop d2 toward a5. Another important line runs from White's bishop f1 through e2 and d3 to the black bishop c4 and king b5. That line pins the black bishop while the king stays on b5. These overlapping jobs explain why moving the knight off b4 is not enough by itself; its destination matters.''',
     '''Qf6 prepares the mating net and releases the king flight Ka5. After that flight, Nd3 is mate: the knight opens bishop d2's diagonal to a5 and blocks Black's queen g3 from interposing on c3 along the third rank. Against Qxg6, however, the required move is Nc2. It opens the rook's b-file check and blocks the queen's diagonal route g6–f5–e4–d3–c2–b1, preventing Qxb1. The f1 bishop's pin of c4 must also remain intact.''',
     '''After Qg5, use Na6 mate. The queen on g5 cuts White's rook h5 off from protecting c5, so the knight on a6 supplies that protection and prevents Kxc5. Nd3 fails against both Qg5 and Qxg6: putting the knight on d3 blocks White's bishop f1 and releases Black's bishop c4, which can answer with Bb3. Other defences often allow Qa6, while the a8 knight moves require Qb6 or Qxb6. The full map accounts for all twenty-five legal replies.''',
     '''Replay the three named branches and say the knight's extra job after each: d3 stops Qc3, c2 stops Qxb1, and a6 guards c5. Then inspect the shared Nd3 error in the queen-move branches, where Bb3 blocks the rook check. This advanced-looking composition rewards a basic habit: do not stop calculating when you see check. Inspect captures, blocks, and king flights on the exact resulting board, including friendly pieces that your own move has accidentally obstructed.''',
     'Qf6 prepares several discoveries and lets the defender determine the knight’s exact destination.',
     [('Qxg6','Nc2#','The queen captures the g6 pawn and gains a diagonal toward b1.','Nc2 opens the rook check, blocks Qxb1, and leaves the f1 bishop’s pin intact.'),
      ('Qg5','Na6#','The queen goes to g5, interrupting the h5 rook’s protection of c5.','Na6 opens the rook check and guards c5 against the king’s capture.'),
      ('Ka5','Nd3#','The king uses the newly available flight a5.','Nd3 opens bishop d2’s check and blocks the queen’s route to the interposing square c3.'),
      ('Nb6','Qxb6#','The a8 knight occupies b6.','The queen captures that knight and checks b5 from b6.')],
     [('Why does Nd3 fail after Qxg6 or Qg5?', 'It blocks bishop f1 and lets Black answer Bb3', 'The black bishop c4 is no longer pinned to the king.', 'A knight cannot move from b4 to d3', 'The move is legal; the resulting defensive resource defeats the mate.'),
      ('Why is Na6 needed after Qg5?', 'It protects c5 when the h5 rook’s line is blocked', 'Without that protection, the king may capture the c5 pawn.', 'It directly gives a knight check to b5', 'A knight on a6 does not attack b5; the rook b1 gives check.')],
     ('Preserve the c4 pin when needed.', 'Block the queen’s exact route.', 'Name the knight’s additional defensive job.'))
